(function(){
  var TA = Java.loadClass('dev.emi.trinkets.api.TrinketsApi');
  var MC = Java.loadClass('net.minecraft.client.Minecraft');
  var P = MC.getInstance().player;
  var map = TA.getPlayerSlots(P);
  var out = { slots: 0 };
  var it = map.entrySet().iterator();
  while (it.hasNext()) {
    var g = it.next().getValue();
    var it2 = g.getSlots().entrySet().iterator();
    while (it2.hasNext()) {
      var st = it2.next().getValue();
      var key = String(st.getGroup()) + '.' + String(st.getName());
      out[key] = String(st.getTranslation().getString());
      out.slots = out.slots + 1;
    }
  }
  return out;
})()
